// Note is the host's own voice: a short factual line the shell posts when it
// changes something the person should see in the thread. It is not a turn --
// no reply follows it, it is never sent to the model, and it renders without a
// bubble. Added additively; the capability list advertises it.
enum class MessageRole : std::uint8_t { User, Assistant, Note };
enum class MessageState : std::uint8_t { Complete, Streaming, Failed, Stopped };

struct ConversationMessage
{
    std::string               id;                // host-assigned, stable across reloads
    MessageRole               role{MessageRole::User};
    MessageState              state{MessageState::Complete};
    std::string               text;
    std::string               client_message_id; // user messages: page-supplied dedup ID
    std::string               in_reply_to;       // assistant messages: the user message ID
    std::string               created_at;        // the host's timestamp when stored; empty before it is
    std::optional<AgentError> error;
    int                       attempt{1};
    std::vector<std::string>  attachment_ids;    // user messages: sent attachment IDs
    std::string               swatch;            // notes: a colour that leads the line, "#RRGGBB"
    // Notes: a file's load report (JSON), which the model reads; the page
    // draws it only as a card, when the Agent could not speak about it.
    std::string               file_report;
    bool                      file_report_card{false};
    // Notes: the receipt for a preset the person saved from a proposal (JSON
    // {name, detail, actionId, undo?, undone?}), which the page draws in
    // place of the text; the text tells the model.
    std::string               receipt;
    // Notes: what the model reads in place of the text, when the line the
    // page draws says less than the model needs.
    std::string               for_model;
    // User messages sent from a print-issue bubble: the issue, its target and
    // the freshness of the evidence (JSON), which the model reads beside the
    // text and the page does not draw.
    std::string               issue_context;
};

} // namespace Slic3r::GUI::JusPrin::Agent

ActionClass action_class_from(const std::string& name)
{
    if (name == "mutation")
        return ActionClass::Mutation;
    if (name == "destructive")
        return ActionClass::Destructive;
    return ActionClass::ReadOnly;
}

// Updates the known fields of an existing JSON object in place, so fields
// written by other builds are preserved.
void write_message_fields(json& entry, const ConversationMessage& message)
{
    entry["id"]      = message.id;
    entry["role"]    = role_name(message.role);
    entry["state"]   = message_state_name(message.state);
    entry["text"]    = message.text;
    entry["attempt"] = message.attempt;
    if (!message.client_message_id.empty())
        entry["clientMessageId"] = message.client_message_id;
    if (!message.in_reply_to.empty())
        entry["inReplyTo"] = message.in_reply_to;
    if (message.error)
        entry["error"] = json{{"code", message.error->code}, {"message", message.error->message},
                              {"retryable", message.error->retryable}};
    else
        entry.erase("error");
    if (!message.attachment_ids.empty())
        entry["attachments"] = message.attachment_ids;
    else
        entry.erase("attachments");
    if (!message.swatch.empty())
        entry["swatch"] = message.swatch;
    else
        entry.erase("swatch");
    if (!message.file_report.empty()) {
        entry["fileReport"]     = message.file_report;
        entry["fileReportCard"] = message.file_report_card;
    } else {
        entry.erase("fileReport");
        entry.erase("fileReportCard");
    }
    if (!message.issue_context.empty())
        entry["issueContext"] = message.issue_context;
    else
        entry.erase("issueContext");
    if (!message.receipt.empty())
        entry["receipt"] = message.receipt;
    else
        entry.erase("receipt");
    if (!message.for_model.empty())
        entry["forModel"] = message.for_model;
    else
        entry.erase("forModel");
}

ConversationMessage read_message(const json& entry)
{
    ConversationMessage message;
    message.id                = entry.value("id", "");
    message.role              = role_from(entry.value("role", "assistant"));
    message.state             = message_state_from(entry.value("state", "complete"));
    message.text              = entry.value("text", "");
    message.attempt           = entry.value("attempt", 1);
    message.client_message_id = entry.value("clientMessageId", "");
    message.in_reply_to       = entry.value("inReplyTo", "");
    message.created_at        = entry.value("createdAt", "");
    if (entry.contains("error") && entry["error"].is_object())
        message.error = AgentError{entry["error"].value("code", ""), entry["error"].value("message", ""),
                                   entry["error"].value("retryable", false)};
    if (entry.contains("attachments") && entry["attachments"].is_array())
        for (const json& id : entry["attachments"])
            if (id.is_string())
                message.attachment_ids.push_back(id.get<std::string>());
    message.swatch           = entry.value("swatch", "");
    message.file_report      = entry.value("fileReport", "");
    message.file_report_card = entry.value("fileReportCard", false);
    message.issue_context    = entry.value("issueContext", "");
    message.receipt          = entry.value("receipt", "");
    message.for_model        = entry.value("forModel", "");
    return message;
}

void write_attachment_fields(json& entry, const AttachmentRecord& record)
{
    entry["id"]           = record.id;
    if (!record.client_id.empty())
        entry["clientId"] = record.client_id;
    entry["originalName"] = record.original_name;
    entry["storedName"]   = record.stored_name;
}

json error_json(const AgentError& error)
{
    return json{{"code", error.code}, {"message", error.message}, {"retryable", error.retryable}};
}

json message_json(const ConversationMessage& message)
{
    json result{{"id", message.id},
                {"role", role_name(message.role)},
                {"state", state_name(message.state)},
                {"text", message.text},
                {"attempt", message.attempt}};
    if (!message.client_message_id.empty())
        result["clientMessageId"] = message.client_message_id;
    if (!message.in_reply_to.empty())
        result["inReplyTo"] = message.in_reply_to;
    // The page times a turn from the person's message; a message from a
    // document written before the stamp was stored has none.
    if (!message.created_at.empty())
        result["createdAt"] = message.created_at;
    if (message.error)
        result["error"] = error_json(*message.error);
    if (!message.attachment_ids.empty())
        result["attachments"] = message.attachment_ids;
    if (!message.swatch.empty())
        result["swatch"] = message.swatch;
    if (!message.file_report.empty()) {
        result["fileReport"]     = json::parse(message.file_report, nullptr, false);
        result["fileReportCard"] = message.file_report_card;
    }
    if (!message.issue_context.empty())
        result["issueContext"] = json::parse(message.issue_context, nullptr, false);
    if (!message.receipt.empty())
        result["receipt"] = json::parse(message.receipt, nullptr, false);
    return result;
}

const char* action_class_name(ActionClass action_class)
{
    switch (action_class) {
    case ActionClass::ReadOnly: return "read_only";
    case ActionClass::Mutation: return "mutation";
    case ActionClass::Destructive: return "destructive";
    }
    return "read_only";
}

