TEST_CASE("a print marker is one saved note the page draws from its data", "[agent][host][print-marker]")
{
    Harness harness;
    harness.handshake();
    ProjectStateDocument& document      = harness.persistence.document();
    const std::string conversation_id   = document.active_conversation_id();
    const std::size_t messages_before   = document.messages(conversation_id).size();
    const std::size_t envelopes_before  = harness.of_type("message_added").size();

    PrinterEvent sent;
    sent.kind       = PrinterEvent::kSent;
    sent.printer    = "Bambu Lab A1 mini 2";
    sent.plate      = 1;
    sent.plate_name = "Clips";
    const std::string id = harness.host.post_printer_event(sent);

    const auto& messages = document.messages(conversation_id);
    REQUIRE(messages.size() == messages_before + 1);
    const ConversationMessage& note = messages.back();
    CHECK(note.id == id);
    CHECK(note.role == MessageRole::Note);
    CHECK(note.text == "Sent to Bambu Lab A1 mini 2");
    CHECK_FALSE(note.created_at.empty());

    // The page gets the marker's data and starts nothing.
    const auto added = harness.of_type("message_added");
    REQUIRE(added.size() == envelopes_before + 1);
    const json& page = added.back()["payload"]["message"];
    CHECK(page["role"] == "note");
    CHECK(page["printerEvent"] == json{{"kind", "sent"}, {"printer", "Bambu Lab A1 mini 2"}, {"plate", 1}, {"plateName", "Clips"}});
    CHECK_FALSE(harness.host.stream_active());

    // It is saved with the project.
    ProjectStateDocument reloaded;
    REQUIRE(reloaded.load(document.dump()) == ProjectStateDocument::LoadResult::Loaded);
    const auto& kept = reloaded.messages(conversation_id);
    REQUIRE_FALSE(kept.empty());
    CHECK(json::parse(kept.back().printer_event) == page["printerEvent"]);

    SECTION("a storage-only upload says nothing was started") {
        PrinterEvent uploaded;
        uploaded.kind    = PrinterEvent::kUploaded;
        uploaded.printer = "Bambu Lab A1 mini 2";
        harness.host.post_printer_event(uploaded);
        const json& upload_page = harness.of_type("message_added").back()["payload"]["message"];
        CHECK(upload_page["text"] == "Uploaded to Bambu Lab A1 mini 2 · not started");
        // No plate number when none is known.
        CHECK(upload_page["printerEvent"] == json{{"kind", "uploaded"}, {"printer", "Bambu Lab A1 mini 2"}});
    }
    SECTION("an unknown kind or a missing printer is refused, and nothing is posted") {
        PrinterEvent unknown;
        unknown.kind    = "printing";
        unknown.printer = "Bambu Lab A1 mini 2";
        CHECK_THROWS_AS(harness.host.post_printer_event(unknown), std::invalid_argument);
        PrinterEvent nameless;
        nameless.kind = PrinterEvent::kSent;
        CHECK_THROWS_AS(harness.host.post_printer_event(nameless), std::invalid_argument);
        CHECK(document.messages(conversation_id).size() == messages_before + 1);
    }
}
